import sys

def solve():
    jumps = []
    try:
        while True:
            line = input()
            if not line:
                break
            # Handle potential empty lines or split by whitespace
            for token in line.split():
                jumps.append(int(token))
    except EOFError:
        pass

    pos = 0
    steps = 0

    while pos < len(jumps):
        jump = jumps[pos]
        steps += 1

        # Part 2 Logic
        if jump >= 3:
            jumps[pos] -= 1
        else:
            jumps[pos] += 1

        pos += jump

    print(steps)

if __name__ == "__main__":
    solve()

