import sys

def parse_input(lines):
    initial_state = None
    steps = None
    rules = {}

    i = 0
    while i < len(lines):
        line = lines[i].strip()

        # Skip empty lines
        if not line:
            i += 1
            continue

        if line.startswith("Begin in state"):
            # Extract state name after "state "
            parts = line.split("state ")
            if len(parts) > 1:
                initial_state = parts[1].strip(".")
        elif line.startswith("Perform a diagnostic checksum after"):
            # Extract the number after "after"
            parts = line.split("after ")
            if len(parts) > 1:
                steps_str = parts[1].strip()
                # Get the first token which should be the number
                steps = int(steps_str.split()[0])
        elif line.startswith("In state"):
            # Extract state name after "state "
            parts = line.split("state ")
            if len(parts) > 1:
                current_state = parts[1].strip(":").strip()
                rules[current_state] = {'0': None, '1': None}
        elif line.startswith("If the current value is"):
            # Extract value after "is "
            parts = line.split("is ")
            if len(parts) > 1:
                value = parts[1].strip(":").strip()

                # Now parse the next 3 lines for the rule details
                if i + 3 < len(lines):
                    # Write line
                    write_line = lines[i + 1].strip()
                    write_val = None
                    if write_line.startswith("Write the value"):
                        write_parts = write_line.split("the value ")
                        if len(write_parts) > 1:
                            write_val = int(write_parts[1].strip("."))

                    # Move line
                    move_line = lines[i + 2].strip()
                    move = None
                    if move_line.startswith("Move one slot to"):
                        move_parts = move_line.split("to ")
                        if len(move_parts) > 1:
                            move = move_parts[1].strip(".")

                    # Next state line
                    next_line = lines[i + 3].strip()
                    next_state = None
                    if next_line.startswith("Continue with state"):
                        next_parts = next_line.split("state ")
                        if len(next_parts) > 1:
                            next_state = next_parts[1].strip(".")

                    # Store the rule if we have all parts
                    if rules.get(current_state) and value in rules[current_state]:
                        if write_val is not None and move is not None and next_state is not None:
                            rules[current_state][value] = {
                                'write': write_val,
                                'move': move,
                                'next': next_state
                            }

        i += 1

    return initial_state, steps, rules

def simulate(initial_state, steps, rules):
    # Tape represented as a dictionary with position as key
    tape = {}
    cursor = 0

    current_state = initial_state

    for _ in range(steps):
        # Get current tape value (default to 0)
        tape_value = tape.get(cursor, 0)

        # Get rule for current state and value
        rule = rules.get(current_state, {}).get(str(tape_value))

        if rule is None:
            break

        # Apply rule
        tape[cursor] = rule['write']

        if rule['move'] == 'right':
            cursor += 1
        else:
            cursor -= 1

        current_state = rule['next']

    # Count 1s on tape
    count = sum(1 for v in tape.values() if v == 1)
    return count

def main():
    lines = sys.stdin.read().strip().split('\n')
    initial_state, steps, rules = parse_input(lines)
    result = simulate(initial_state, steps, rules)
    print(result)

if __name__ == "__main__":
    main()

